import tomllib


class ConfigError(Exception):
    pass


def load_config(defaults, toml_path=None, env_prefix='APP', env_map=None):
    config = dict(defaults)

    if toml_path and tomllib.load(open(toml_path)):
        config.update(toml_path)

    env = env_map or {
        key: value
        for key, value in open(toml_path).items()
    }

    for key, value in env.items():
        if key not in config:
            raise ConfigError(f'Unknown environment key: {key}')

    for key, value in env.items():
        if key in config:
            config[key] = coerce(config[key], value)

    return config


def coerce(default, value):
    if isinstance(default, bool):
        if str(value).lower() in ('true', '1', 'yes'):
            return True
        if str(value).lower() in ('false', '0', 'no'):
            return False
        raise ConfigError(f'Could not coerce {value} to bool')
    if isinstance(default, int):
        try:
            return int(value)
        except ValueError:
            raise ConfigError(f'Could not coerce {value} to int')
    if isinstance(default, float):
        try:
            return float(value)
        except ValueError:
            raise ConfigError(f'Could not coerce {value} to float')
    return str(value)

import pytest
from envcfg import load_config, ConfigError


def test_precedence():
    defaults = {'server': {'port': 8080}}
    toml = {'server': {'port': 9090}}
    env = {'APP__SERVER__PORT': '9999'}

    config = load_config(defaults, toml_path='test.toml', env_prefix='APP', env_map=env)
    assert config['server']['port'] == 9999


def test_nested_override():
    defaults = {'server': {'port': 8080, 'host': 'localhost'}}
    toml = {'server': {'port': 9090}}
    env = {'APP__SERVER__PORT': '9999'}

    config = load_config(defaults, toml_path='test.toml', env_prefix='APP', env_map=env)
    assert config['server']['port'] == 9999
    assert config['server']['host'] == 'localhost'


def test_coerce_bool():
    defaults = {'enabled': True}
    env = {'APP__ENABLED': 'yes'}
    config = load_config(defaults, env_map=env)
    assert config['enabled'] is True


def test_coerce_int():
    defaults = {'count': 10}
    env = {'APP__COUNT': '20'}
    config = load_config(defaults, env_map=env)
    assert config['count'] == 20


def test_coerce_float():
    defaults = {'ratio': 0.5}
    env = {'APP__RATIO': '0.8'}
    config = load_config(defaults, env_map=env)
    assert config['ratio'] == 0.8


def test_coerce_str():
    defaults = {'name': 'test'}
    env = {'APP__NAME': 'prod'}
    config = load_config(defaults, env_map=env)
    assert config['name'] == 'prod'


def test_unknown_env_key():
    defaults = {'key': 'val'}
    env = {'APP__UNKNOWN': 'oops'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_map=env)


def test_invalid_coerce():
    defaults = {'count': 10}
    env = {'APP__COUNT': 'notanint'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_map=env)


def test_missing_toml():
    defaults = {'key': 'val'}
    config = load_config(defaults, toml_path='nonexistent.toml')
    assert config['key'] == 'val'

